import { Card } from "../../card/card";
import { Table } from "../../table/table";
import { SummaryTile } from "../../summaryTile/summaryTile";
import { Banner } from "../../banner/banner";
import { Accordion } from "../../accordion/accordion";
import { CardContainer } from "../../cardContainer/cardContainer";
import { isGridItem } from "./isGridItem";
import { BannerUpsell } from "../../banner/bannerUpsell";
import { FormStepper } from "../../formStepper/formStepper";
import { FormStepperButtons } from "../../formStepperButtons/formStepperButtons";
export const DEFAULT_SUPPORTED_COMPONENTS = [
    // Data
    Table,
    Card,
    SummaryTile,
    // Feedback
    Banner,
    BannerUpsell,
    // Layout
    Accordion,
    // Form
    FormStepper,
    FormStepperButtons,
    // Inner
    CardContainer
];
export const getAllowedComponent = (child) => {
    // for React common components ("div", "span", etc.)
    if (typeof child.type === "string") {
        return child;
    }
    if (DEFAULT_SUPPORTED_COMPONENTS.includes(child.type) || isGridItem(child)) {
        return child;
    }
    return null;
};
